{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["composer","after-panel"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Plan your trip, day by day","lede":"Tell us where, when and how much – we'll shape each day around it.","runLabel":"Plan my trip","columns":"2"},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["group-where","group-budget","group-who","group-else"]}}
{"op":"add","path":"/elements/group-where","value":{"type":"FieldGroup","props":{"title":"Where and when"},"children":["trip-title","city","country","dates","must-see"]}}
{"op":"add","path":"/elements/trip-title","value":{"type":"Input","props":{"label":"Trip name","name":"title","placeholder":"Lisbon long weekend","value":{"$bindState":"/inputs/request/title"},"checks":[{"type":"required","message":"Give the trip a name"}]},"children":[]}}
{"op":"add","path":"/elements/city","value":{"type":"Input","props":{"label":"City","name":"city","value":{"$bindState":"/inputs/request/stay/city"},"checks":[{"type":"required","message":"Which city?"}]},"children":[]}}
{"op":"add","path":"/elements/country","value":{"type":"Select","props":{"label":"Country","name":"country","options":["France","Italy","Japan","Portugal","Spain","United States"],"value":{"$bindState":"/inputs/request/stay/country"},"checks":[{"type":"required","message":"Pick a country"}]},"children":[]}}
{"op":"add","path":"/elements/dates","value":{"type":"DateRange","props":{"label":"Arriving and leaving","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}},"children":[]}}
{"op":"add","path":"/elements/must-see","value":{"type":"Chips","props":{"label":"Must-sees","placeholder":"Add a place and press Enter","value":{"$bindState":"/inputs/request/stay/must_see"}},"children":[]}}
{"op":"add","path":"/elements/group-budget","value":{"type":"FieldGroup","props":{"title":"Budget and pace"},"children":["budget","currency","pace","style"]}}
{"op":"add","path":"/elements/budget","value":{"type":"NumberInput","props":{"label":"Total budget","name":"budget","value":{"$bindState":"/inputs/request/budget"}},"children":[]}}
{"op":"add","path":"/elements/currency","value":{"type":"Segmented","props":{"label":"Currency","name":"currency","options":["EUR","USD","GBP","JPY"],"value":{"$bindState":"/inputs/request/currency"}},"children":[]}}
{"op":"add","path":"/elements/pace","value":{"type":"Segmented","props":{"label":"Pace","name":"pace","options":["slow","balanced","packed"],"value":{"$bindState":"/inputs/request/pace"}},"children":[]}}
{"op":"add","path":"/elements/style","value":{"type":"Segmented","props":{"label":"Mostly about","name":"style","options":["culture","food","nature","nightlife","family"],"value":{"$bindState":"/inputs/request/style"}},"children":[]}}
{"op":"add","path":"/elements/group-who","value":{"type":"FieldGroup","props":{"title":"Who's going"},"children":["travellers","with-children","accessibility"]}}
{"op":"add","path":"/elements/travellers","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add a traveller"},"children":[]}}
{"op":"add","path":"/elements/with-children","value":{"type":"Checkbox","props":{"label":"Children are coming","name":"with_children","checked":{"$bindState":"/inputs/request/with_children"}},"children":[]}}
{"op":"add","path":"/elements/accessibility","value":{"type":"Input","props":{"label":"Accessibility needs","name":"accessibility","placeholder":"Step-free routes, short walks…","value":{"$bindState":"/inputs/request/accessibility"}},"children":[]}}
{"op":"add","path":"/elements/group-else","value":{"type":"FieldGroup","props":{"title":"Anything else"},"children":["notes","inspiration"]}}
{"op":"add","path":"/elements/notes","value":{"type":"Textarea","props":{"label":"Notes for the planner","name":"notes","rows":3,"value":{"$bindState":"/inputs/request/notes"}},"children":[]}}
{"op":"add","path":"/elements/inspiration","value":{"type":"MthdsField","props":{"path":"/inputs/inspiration","label":"Inspiration image","hint":"Optional – a picture of the trip you have in mind."},"children":[]}}
{"op":"add","path":"/elements/after-panel","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["returns-note","needs-note"]}}
{"op":"add","path":"/elements/returns-note","value":{"type":"Text","props":{"text":"You'll get a named plan with a short overview, each day in order, estimated costs by category with a total, and practical notes for getting around.","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/needs-note","value":{"type":"Text","props":{"text":"The trip details are needed to plan; the image is optional.","variant":"muted"},"children":[]}}
